def translate(text):
 if text in EXACT:return EXACT[text]
 s=re.sub(r'(?<=[A-Za-z])[–—](?=[A-Za-z])','-',text)
 protected={'Great White':'\ue000','Liberator Plus':'\ue001'}
 for name,token in protected.items():s=re.sub(re.escape(name),token,s,flags=re.I)
