 s=s.replace('с двумя #2 Hi-Fi® нити','с двумя нитями Hi-Fi® №2').replace('с тремя #2 Hi-Fi® нити','с тремя нитями Hi-Fi® №2').replace('с одной #2 Hi-Fi нить','с одной нитью Hi-Fi №2')
